#include <iostream>
#include <vector>

long long fib(int n) {
    if (n <= 1) return n;
    std::vector<long long> f(n + 1);
    f[0] = 0; f[1] = 1;
    for (int i = 2; i <= n; i++) f[i] = f[i-1] + f[i-2];
    return f[n];
}

int main() {
    int n;
    while (std::cin >> n) {
        std::cout << fib(n) << std::endl;
    }
    return 0;
}
